// = JS String(v ?? '')
fn str_qq(v: Option<&Value>) -> String {
    match v {
        None | Some(Value::Null) => String::new(),
        Some(Value::String(s)) => s.clone(),
        Some(Value::Bool(b)) => b.to_string(),
        Some(n @ Value::Number(_)) => n.to_string(),
        Some(o) => o.to_string(),
    }
}
// = JS String(v) (no ??)
fn js_string(v: &Value) -> String {
    match v {
        Value::Null => "null".into(),
        Value::String(s) => s.clone(),
        Value::Number(n) => n.to_string(),
        Value::Bool(b) => b.to_string(),
        Value::Array(a) => a.iter().map(js_string).collect::<Vec<_>>().join(","),
        Value::Object(_) => "[object Object]".into(),
    }
}
// = JS Number(v)
fn js_number(v: Option<&Value>) -> f64 {
    match v {
        None => f64::NAN,
        Some(Value::Null) => 0.0,
        Some(Value::Bool(b)) => if *b { 1.0 } else { 0.0 },
        Some(Value::Number(n)) => n.as_f64().unwrap_or(f64::NAN),
        Some(Value::String(s)) => { let t = s.trim(); if t.is_empty() { 0.0 } else { t.parse::<f64>().unwrap_or(f64::NAN) } },
        Some(_) => f64::NAN,
    }
}
// = JS `n >>> 0` (ToUint32): non-finite → 0, else truncate toward zero and wrap mod 2^32.
fn js_to_uint32(n: f64) -> u32 {
    if !n.is_finite() { return 0; }
    n.trunc().rem_euclid(4294967296.0) as u32
}

fn slot_re() -> &'static Regex {
    static R: OnceLock<Regex> = OnceLock::new();
    R.get_or_init(|| Regex::new(r"\{(\w+)\}").unwrap())
}

/// fill(tpl, slots) — replace every `{name}` in tpl from slots; any missing/null/empty-string
/// slot disqualifies the whole template (returns null) instead of leaving a blank behind.
pub fn fill(tpl: &Value, slots: &Value) -> Value {
    let tpl_s = str_qq(Some(tpl));
    let mut ok = true;
    let text = slot_re().replace_all(&tpl_s, |caps: &regex::Captures| {
        let k = &caps[1];
        match slots.get(k) {
            None | Some(Value::Null) => { ok = false; String::new() }
            Some(Value::String(s)) if s.is_empty() => { ok = false; String::new() }
            Some(v) => js_string(v),
        }
    });
    if ok { json!(text.into_owned()) } else { Value::Null }
}

/// rng(seed) — deterministic LCG generator (TRANSITIVE: the JS returns a closure, not a JSON
/// value). Same stepping constants as js_math::lcg_next; `Number(seed) >>> 0`, 0 replaced by 1.
pub fn rng(seed: &Value) -> impl FnMut() -> f64 {
    let mut s = js_to_uint32(js_number(Some(seed)));
    if s == 0 { s = 1; }
    move || {
        s = crate::js_math::lcg_next(s);
        (s as f64) / 4294967296.0
    }
}

/// makePicker(rand) — seeded pick that avoids repeating the immediately-previous choice of the
/// same bank (TRANSITIVE: takes AND returns a closure). `bank_key` is coerced with String(v ??
/// '') to key the last-pick map, matching the JS Map's string bank keys.
pub fn makePicker(mut rand: impl FnMut() -> f64) -> impl FnMut(&Value, &Value, &Value) -> Value {
    let mut last: HashMap<String, usize> = HashMap::new();
    move |bank_key: &Value, bank: &Value, slots: &Value| -> Value {
        let empty = vec![];
        let bank_arr = bank.as_array().unwrap_or(&empty);
        let mut usable: Vec<usize> = Vec::new();
        for (i, t) in bank_arr.iter().enumerate() {
            if !fill(t, slots).is_null() { usable.push(i); }
        }
        if usable.is_empty() { return Value::Null; }
        let key = str_qq(Some(bank_key));
        let pool: Vec<usize> = if usable.len() > 1 {
            match last.get(&key) {
                Some(&li) => usable.iter().copied().filter(|&i| i != li).collect(),
                None => usable.clone(),
            }
        } else {
            usable.clone()
        };
        let idx = ((rand() * pool.len() as f64).floor() as usize).min(pool.len() - 1);
        let picked_i = pool[idx];
        last.insert(key, picked_i);
        fill(&bank_arr[picked_i], slots)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn t_parses_with_the_pressed_shape() {
        let v: &Value = &T;
        assert_eq!(v.as_object().expect("object").len(), 74, "pressed key count");
    }

    #[test]
    fn bank_tags_parses_with_the_pressed_shape() {
        let v: &Value = &BANK_TAGS;
        assert_eq!(v.as_object().expect("object").len(), 74, "pressed key count");
    }

    #[test]
    fn bank_count_parses_with_the_pressed_shape() {
        let v: &Value = &BANK_COUNT;
        assert_eq!(v.as_i64().expect("int"), 74, "pressed value");
    }

    #[test]
    fn fill_slots_or_disqualifies() {
        assert_eq!(fill(&json!("{a} and {a}"), &json!({ "a": "x" })), json!("x and x"));
        assert_eq!(fill(&json!("hello {missing}"), &json!({})), Value::Null);
        assert_eq!(fill(&json!("hello {a}"), &json!({ "a": "" })), Value::Null);
        assert_eq!(fill(&json!("hello {a}"), &json!({ "a": null })), Value::Null);
        assert_eq!(fill(&json!("no slots here"), &Value::Null), json!("no slots here"));
        assert_eq!(fill(&json!("count {n}"), &json!({ "n": 0 })), json!("count 0"));
        assert_eq!(fill(&json!("flag {f}"), &json!({ "f": false })), json!("flag false"));
    }

    #[test]
    fn rng_matches_lcg_contract_and_zero_seeds_as_one() {
        let mut r0 = rng(&json!(0)); // seed 0 → replaced by 1, same stream as seed 1
        let mut r1 = rng(&json!(1));
        assert_eq!(r0(), r1());
        assert_eq!(r0(), r1());
        let mut fresh = rng(&json!(1));
        let s1 = crate::js_math::lcg_next(1);
        assert_eq!(fresh(), (s1 as f64) / 4294967296.0);
    }

    #[test]
    fn make_picker_never_repeats_consecutively_and_nulls_when_unfillable() {
        let bank = json!(["A{x}", "B{x}", "C{x}"]);
        let slots = json!({ "x": "!" });
        let mut pick = makePicker(rng(&json!(123)));
        let key = json!("bank");
        let mut prev: Option<Value> = None;
        for _ in 0..30 {
            let out = pick(&key, &bank, &slots);
            assert_ne!(Some(out.clone()), prev);
            prev = Some(out);
        }
        let mut pick2 = makePicker(rng(&json!(1)));
        assert_eq!(pick2(&json!("k"), &json!(["{missing}"]), &json!({})), Value::Null);
    }
}
